create table if not exists public.hot_seat_moderation (id uuid primary key default gen_random_uuid(),host_id uuid not null references public.hot_seat_hosts(id) on delete cascade,user_id uuid not null,action text not null check(action in ('mute','ban')),reason text,expires_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null default auth.uid());
alter table public.hot_seat_moderation enable row level security;
revoke all on public.hot_seat_moderation from anon,authenticated;
grant select on public.hot_seat_moderation to authenticated;
drop policy if exists "hotseat moderation admin read" on public.hot_seat_moderation;
create policy "hotseat moderation admin read" on public.hot_seat_moderation for select to authenticated using(private.is_admin(auth.uid()));
create or replace function public.hot_seat_user_moderated(p_host_id uuid,p_user_id uuid,p_action text default null) returns boolean language sql stable security definer set search_path=public,private as $$ select exists(select 1 from public.hot_seat_moderation m where m.host_id=p_host_id and m.user_id=p_user_id and (p_action is null or m.action=p_action) and (m.expires_at is null or m.expires_at>now())) $$;
create or replace function public.admin_hot_seat_moderate(p_host_id uuid,p_user_id uuid,p_action text,p_minutes integer default 30,p_reason text default null) returns public.hot_seat_moderation language plpgsql security definer set search_path=public,private as $$ declare r public.hot_seat_moderation; begin if not private.is_admin(auth.uid()) then raise exception 'Admin access required'; end if; if p_action not in ('mute','ban') then raise exception 'Invalid moderation action'; end if; if p_minutes<1 or p_minutes>10080 then raise exception 'Invalid duration'; end if; insert into public.hot_seat_moderation(host_id,user_id,action,reason,expires_at,created_by) values(p_host_id,p_user_id,p_action,nullif(trim(coalesce(p_reason,'')),''),now()+make_interval(mins=>p_minutes),auth.uid()) returning * into r; return r; end $$;
revoke all on function public.hot_seat_user_moderated(uuid,uuid,text) from public,anon; grant execute on function public.hot_seat_user_moderated(uuid,uuid,text) to authenticated;
revoke all on function public.admin_hot_seat_moderate(uuid,uuid,text,integer,text) from public,anon; grant execute on function public.admin_hot_seat_moderate(uuid,uuid,text,integer,text) to authenticated;